<?php require 'includes/auth.php'; require_login(); $cart=$_SESSION['cart']??[]; if(!$cart){header('Location: cart.php');exit;} $in=implode(',',array_fill(0,count($cart),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE id IN ($in)");$s->execute(array_keys($cart));$items=$s->fetchAll();$total=0;foreach($items as $p)$total+=$p['price']*$cart[$p['id']]; if($_SERVER['REQUEST_METHOD']==='POST'){ $u=user();$ord='HK'.date('ymdHis').random_int(10,99);$pdo->beginTransaction();$st=$pdo->prepare("INSERT INTO orders(order_no,user_id,total,status,customer_name,phone,address) VALUES(?,?,?,?,?,?,?)");$st->execute([$ord,$u['id'],$total,'pending',$_POST['name'],$_POST['phone'],$_POST['address']]);$oid=$pdo->lastInsertId();$it=$pdo->prepare("INSERT INTO order_items(order_id,product_id,qty,price) VALUES(?,?,?,?)");foreach($items as $p)$it->execute([$oid,$p['id'],$cart[$p['id']],$p['price']]);$pdo->commit();unset($_SESSION['cart']);header("Location: invoice.php?order=".$oid);exit;}?>
<!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Checkout</title><link rel=stylesheet href=assets/style.css></head><body><main class=checkout><h1>Checkout</h1><p>Total pesanan: <b><?=rupiah($total)?></b></p><form method=post><input name=name required placeholder="Nama lengkap" value="<?=e(user()['name'])?>"><input name=phone required placeholder="Nomor WhatsApp"><textarea name=address required placeholder="Alamat lengkap"></textarea><button class=btn>Konfirmasi Pesanan</button></form></main></body></html>
